#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;
unordered_map<char,int>v={{'I',1},{'V',5},{'X',10},{'L',50},{'C',100},{'D',500},{'M',1000}};
int r=0;
for(int i=0;i<(int)s.size();++i){
if(i+1<(int)s.size()&&v[s[i]]<v[s[i+1]])r-=v[s[i]];else r+=v[s[i]];}
printf("%d\n",r);return 0;}

